UPDATE ins_tra_counterparty SET IS_ACCUMULATED = '1' WHERE DELFLAG_ = '1' AND (STATUS = '6' or STATUS = '2') AND (IS_ACCUMULATED != '1') AND (Major_Type != 1 ) AND (IS_TRADE_AGREEMENT != 1 )
AND DATE_FORMAT(TRAN_DATE, '%Y')=#{year}
AND Tra_sub_Name = #{traSubName}
and REL_NUMBER IN ( SELECT unisc_code FROM bus_rel_org WHERE mem_group = (SELECT mem_group FROM bus_rel_org WHERE unisc_code = #{relNumber}) )
AND trans_num in ( SELECT t.TRANS_NUM from (SELECT c.TRANS_NUM FROM `ins_tra_counterparty` c where c.REL_NUMBER =#{relNumber}) t )

UPDATE ins_tra_counterparty
SET STATUS = #{status}
WHERE
TRANS_NUM = #{transNum}

update ins_tra_counterparty
set REL_TRADE_AMOUNT = #{relTrandeAmount},PRAC_TRADE_AMOUNT = #{relTrandeAmount},TRAN_DATE = #{contractDate},STATUS = #{Status},TOTAL_NOT_CLEAN_TRADE_AMOUNT=#{bigDecimalOld}
 WHERE
TRANS_NUM = #{transNum}

