select PID, REL_ID, REL_TYPE, REL_NAME, REL_NUMBER, TOTAL_TRADE_AMOUNT, TRADE_AMOUNT TRANS_NUM, TENANT_ID_, Tra_sub_Name, STATUS, TRAN_DATE, REL_TRADE_AMOUNT, MAJOR_TRADE, DELFLAG_, Major_Type, CERT_TYPE, TOTAL_NOT_CLEAN_TRADE_AMOUNT from ins_tra_counterparty where STATUS in ('1','3','4') AND (IS_ACCUMULATED = '0') and DELFLAG_ = '1'
